<section id="schedule" class="section alt"><div class="container"><p class="eyebrow">Программа</p><h2>Программа конференции</h2><?php foreach($schedule as $day): ?><h3 class="day-title"><?= $day['label'] ?></h3><ol class="events"><?php foreach($day['events'] as $e): ?><li class="event"><time><?= $e['time'] ?></time><div><strong><?= $e['title'] ?></strong><p><?= ($e['speaker'] ?? '').' · '.$e['location'] ?></p></div></li><?php endforeach; ?></ol><?php endforeach; ?></div></section>
